D=[['拉丁 domus → dominus／domina','家、房屋 → 男主人／女主人，主人、掌权者']]
DA=D+[['拉丁 dominari → dominans／dominantem','作主人、统治 → 居支配地位的'],['古法语 dominant／直接拉丁 → 英语 dominant','掌权的；占主导的']]
DN=D+[['拉丁 dominari → dominatio → 古法语 dominacion','统治 → 统治、支配这一行为'],['中古英语 domynacion → domination','支配、控制；独立名词借入']]
DV=D+[['拉丁 dominari → dominatus；另一路英语 domination','统治的分词材料；已有的支配名词'],['英语 dominate','可解释为拉丁分词词干构词，或从 domination 逆构']]
DP=D+[['拉丁 dominium → 中世纪拉丁 domanium → 法语 domaine','所有权、领地'],['英语 domain','领地 → 专业领域、系统中的范围']]
DG=D+[['通俗拉丁 *dominarium〔重构〕→ 古法语 dongier／dangier','领主的权力；能伤害别人的权力'],['盎格鲁法语 daunger → 中古英语 daunger → danger','受他者支配的处境 → 遭受损害的危险']]
DY=D+[['通俗拉丁 *dominarium → 古法语 dangier → dangeros','权力、危险 → 有危险的'],['盎格鲁法语 dangerous → 中古英语 daungerous → dangerous','形容词独立借入，后来稳定为危险的']]
DE=DG+[['英语 en- + danger → endanger','使进入危险处境']]
DM=D+[['后期拉丁 domna → 古法语 dame → 中古英语 dame','女主人、女士、母亲'],['英语 dame','女性称号；女士；某些戏剧角色']]
PD=D+[['中世纪拉丁 prae- + dominari 的复合词族 → 法语 prédominant','居于更前、更优越地位的'],['英语 predominant','最主要的；数量或影响占上风的']]
DC=D+[['拉丁 dominium；近代拉丁 con- + dominium → condominium','所有、支配 → 共同统治'],['英语 condominium','共同管辖；后来用于单元分别所有、公共部分共有的住宅']]
def A(h,a,b):return h+[[a,b]]
